const content=window.SITE_CONTENT;const fields=document.querySelector('#fields');
content.faq.forEach(([q,a],i)=>{const f=document.createElement('fieldset');const l=document.createElement('label');l.textContent=q;const input=document.createElement('textarea');input.name='faq-'+i;input.value=a;input.required=true;input.maxLength=3000;l.append(input);f.append(l);fields.append(f)});
function updated(){return {...content,faq:content.faq.map(([q],i)=>[q,document.querySelector(`[name="faq-${i}"]`).value.trim()])}}
document.querySelector('#editor').onsubmit=async e=>{e.preventDefault();const status=document.querySelector('#status');status.textContent='Salvando…';try{const r=await fetch('/api/content',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({faq:updated().faq})});if(!r.ok)throw Error();status.textContent='Respostas salvas. Recarregue o site para ver as mudanças.'}catch{status.textContent='Salvar diretamente só está disponível na prévia local. Use “Baixar configuração” para guardar suas alterações.'}};
document.querySelector('#export').onclick=()=>{const blob=new Blob(['window.SITE_CONTENT = '+JSON.stringify(updated(),null,2)+';\n'],{type:'text/javascript'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='content.js';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
